import{_ as a,o as l,a as i,b as e}from"./app.C41L12d5.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"矩阵计算","link":"/api/SIMD-API/adv_api/cube_compute/cube_compute"},{"text":"Matmul核函数（Kernel）侧接口","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Matmul_Kernel"},{"text":"Matmul模板参数","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Matmul_template_params"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Matmul_template_params.md","filePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Matmul_template_params.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788515292000}'),n={name:"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Matmul_template_params.md"};function s(p,t,d,r,c,u){return l(),i("div",null,[...t[0]||(t[0]=[e(`<div><article class="markdown-body"><h1>Matmul模板参数</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>创建Matmul对象时需要传入：</p><ul><li><p>A、B、C、Bias的参数类型信息，类型信息通过MatmulType来定义，包括：内存逻辑位置、数据格式、数据类型、是否转置、数据排布和是否开启L1复用。</p></li><li><p>MatmulConfig信息（可选），用于配置Matmul模板信息以及相关的配置参数。不配置默认使用Norm模板。</p><span data-filter="310b">针对Atlas 200I/500 A2 推理产品，当前只支持使用默认的Norm模板。</span></li></ul><div data-filter="950,A3,910b,310p,310b,x90"><p><a id="matmul-callback-func"></a></p><ul><li><p>MatmulCallBackFunc回调函数信息（可选），用于配置A矩阵从GM拷贝到L1 Buffer（A1）、B矩阵从GM拷贝到L1 Buffer（B1）、计算结果从L0C Buffer（CO1）拷贝到GM的自定义函数。当前支持如下产品型号：</p><div data-filter="950"><p>Ascend 950PR/Ascend 950DT</p></div><div data-filter="A3"><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品</p></div><div data-filter="910b"><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品</p></div><div data-filter="x90"><p>Kirin X90</p></div></li><li><p>MatmulPolicy信息（可选），用于配置Matmul可拓展模块策略。不配置使用默认模板策略。当前支持如下产品型号：</p><div data-filter="950"><p>Ascend 950PR/Ascend 950DT</p></div><div data-filter="A3"><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品</p></div><div data-filter="910b"><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品</p></div><div data-filter="310b"><p>Atlas 200I/500 A2 推理产品</p></div><div data-filter="310p"><p>Atlas 推理系列产品AI Core</p></div><div data-filter="x90"><p>Kirin X90</p></div></li></ul></div><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><p>Matmul模板参数如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>template &lt;class A_TYPE, class B_TYPE, class C_TYPE, class BIAS_TYPE = C_TYPE, const auto&amp; MM_CFG = CFG_NORM, class MM_CB = MatmulCallBackFunc&lt;nullptr, nullptr, nullptr&gt;, MATMUL_POLICY_DEFAULT_OF(MatmulPolicy)&gt;
</code></pre></div><ul><li><p>A_TYPE、B_TYPE、C_TYPE类型信息通过<a href="Matmul_usage.html#table1188045714378">MatmulType</a>来定义。</p></li><li><p>auto类型的参数MM_CFG（可选）：</p><ul><li><p>支持MatmulConfig类型：</p><p>Matmul模板信息，具体内容见<a href="MatmulConfig.html">MatmulConfig</a>。</p></li><li><p>支持MatmulApiStaticTiling类型：</p><p>MatmulApiStaticTiling参数说明见<a href="#table7939847143412">表1</a>。</p><p>MatmulApiStaticTiling结构体中包括一组常量化Tiling参数和MatmulConfig结构。这种类型参数的定义方式为，通过调用<a href="MatmulConfig.html">MatmulConfig</a>章节中介绍的获取模板的接口，指定(singleM, singleN, singleK, baseM, baseN, baseK)参数，获取自定义模板；将该模板传入<a href="GetMatmulApiTiling.html">GetMatmulApiTiling</a>接口，得到常量化的参数。这种常量化的方式将得到MatmulApiStaticTiling结构体中定义的一组常量化参数，可以优化Matmul计算中的Scalar计算。当前支持定义为MatmulApiStaticTiling常量化的Tiling参数的模板有：Norm、IBShare、MDL模板。MxMatmul场景支持定义为MatmulApiStaticTiling常量化的Tiling参数的模板有：Norm、MDL模板。</p></li></ul></li><li><p>MM_CB（可选），用于支持不同的搬入搬出需求，实现定制化的搬入搬出功能。具体内容见<a href="MatmulCallBackFunc.html">MatmulCallBackFunc</a>。</p></li><li><p>MATMUL_POLICY_DEFAULT_OF(MatmulPolicy)（可选），用于配置Matmul可拓展模块的策略。当前支持不配置该参数（使用默认模板策略）或者配置1个MatmulPolicy参数。</p><p>MATMUL_POLICY_DEFAULT_OF定义如下，用于简化MATMUL_POLICY的类型声明。该模板参数的详细使用方式请参考<a href="MatmulPolicy.html">MatmulPolicy</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>#define MATMUL_POLICY_DEFAULT_OF(DEFAULT)      \\
template &lt;const auto&amp; = MM_CFG, typename ...&gt;  \\
        class MATMUL_POLICY = AscendC::Impl::Detail::DEFAULT
</code></pre></div></li></ul><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> MatmulApiStaticTiling常量化Tiling参数说明</p><p><span id="table7939847143412"></span></p><table><thead><tr><th>参数</th><th>数据类型</th><th>说明</th></tr></thead><tbody><tr><td>M, N, Ka, Kb,<br><br>singleCoreM, singleCoreN, singleCoreK,<br><br>baseM, baseN, baseK,<br><br>depthA1, depthB1,<br><br>stepM， stepN，stepKa，stepKb,<br><br>isBias,<br><br>transLength,<br><br>iterateOrder,<br><br>dbL0A, dbL0B,<br><br>dbL0C,<br><br>shareMode,<br><br>shareL1Size,<br><br>shareL0CSize,<br><br>shareUbSize,<br><br>batchM,<br><br>batchN,<br><br>singleBatchM,<br><br>singleBatchN,<br><br>mxTypePara</td><td>int32_t</td><td>与<a href="../Matmul_Tiling/TCubeTiling_struct.html">TCubeTiling</a>结构体中各同名参数含义一致。本结构体中的参数是常量化后的常数值。</td></tr><tr><td>cfg</td><td><a href="MatmulConfig.html#matmulconfig-params">MatmulConfig</a></td><td>Matmul模板的参数配置。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><p>无</p><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 用户自定义回调函数
void DataCopyOut(
    const __gm__ void* gm, const LocalTensor&lt;int8_t&gt;&amp; co1Local, const void* dataCopyOutParams, const uint64_t tilingPtr,
    const uint64_t dataPtr);
void CopyA1(
    const AscendC::LocalTensor&lt;int8_t&gt;&amp; aMatrix, const __gm__ void* gm, int row, int col, int useM, int useK,
    const uint64_t tilingPtr, const uint64_t dataPtr);
void CopyB1(
    const AscendC::LocalTensor&lt;int8_t&gt;&amp; bMatrix, const __gm__ void* gm, int row, int col, int useK, int useN,
    const uint64_t tilingPtr, const uint64_t dataPtr);

// 定义创建对象时需要传入的A、B、C、Bias参数类型信息
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; aType;
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; bType;
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; cType;
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; biasType;

// 使用MDL模板，创建Matmul实例
AscendC::Matmul&lt;aType, bType, cType, biasType, CFG_MDL&gt; mm1;

AscendC::MatmulConfig mmConfig{false /*不使用Norm模板*/,          true /*使用BasicBlock模板*/,
                               false /*不使用MDL模板*/,           128 /*Matmul计算时base块M轴长度*/,
                               128 /*Matmul计算时base块N轴长度*/, 64 /*Matmul计算时base块K轴长度*/};
mmConfig.enUnitFlag = false; // 不开启UnitFlag功能
// 使用自定义的mmConfig，创建Matmul实例
AscendC::Matmul&lt;aType, bType, cType, biasType, mmConfig&gt; mm2;

// 使用NORM模板、自定义的mmConfig和自定义的回调函数，创建Matmul实例
AscendC::Matmul&lt;aType, bType, cType, biasType, CFG_NORM, AscendC::MatmulCallBackFunc&lt;DataCopyOut, CopyA1, CopyB1&gt;&gt; mm3;
</code></pre></div></article></div>`,1)])])}const M=a(n,[["render",s]]);export{m as __pageData,M as default};
